"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[11518],{85044:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ThrowableHandler","desc":"Category handler for thrown weapons (grenade + Bomb). On activate it gates on the\\nthrow cooldown and plays the throw animation, pausing the TrajectoryPreview line\\nuntil the track stops; at its `Release` marker (no animation = at once) it plays\\nthe throw sound and sends `ReqThrowProjectile` from\\n`TrajectoryPreview.getThrowOriginDir` (the same origin + direction the arc uses).\\nUnequipped before the release = no throw. The projectile instance is server-spawned and replicates to every client (no local\\ncosmetic). Manual detonation (Bomb) is handled globally by\\nThrowableDetonateController, which sends `ReqDetonate` on G regardless of the\\nequipped Tool. Damage + detonation are server-side.","realm":["Client"],"source":{"line":16,"path":"src/StarterPlayer/StarterPlayerScripts/WeaponHandlers/ThrowableHandler.luau"}}')}}]);